"""Lossless document layout and explicit structural comparison entry points."""
import html

JSON_TOOLS = [
    ('json-minify', 'JSON minify / format', 'Data formats', 'Minify, format or validate JSON without rounding numbers or rewriting string escapes. Measure UTF-8 bytes locally.', 'code'),
    ('json-compare', 'JSON compare', 'Data formats', 'Compare JSON values, ignore object key order and find changes by path. Arrays keep their order; numbers compare exactly.', 'code'),
]
MINIFY_SAMPLE = '{\n  "id": 9007199254740993,\n  "message": "keep  two spaces",\n  "values": [1e+30, true, null]\n}'
COMPARE_LEFT = '{\n  "id": "001",\n  "active": true,\n  "tags": ["red", "blue"],\n  "note": null\n}'
COMPARE_RIGHT = '{\n  "tags": ["blue", "red"],\n  "id": "001",\n  "active": false,\n  "note": null,\n  "region": "EU"\n}'


def file_field(input_id, note_id, label):
    return f'<div class="data-file"><label for="{input_id}">{label}</label><input type="file" id="{input_id}" accept=".json,.txt,application/json"><p class="hint" id="{note_id}" role="status"></p></div>'


def json_workflow_pages(tool_head, segmented, copy, docs, extra_section, ad_slot, related):
    minify = tool_head('json-minify', 'DATA FORMATS', 'JSON minify, format & validate', 'Remove unnecessary JSON whitespace, format a document for reading, or check its syntax. Keep number tokens and string content intact; see the actual UTF-8 byte change.')
    minify += '<section class="workbench json-workbench"><div class="bench-toolbar">'+segmented([('minify', 'Minify'), ('format', 'Format'), ('validate', 'Validate')], 'json-modes')+'<span class="quiet">Source tokens preserved · runs locally</span></div><div class="bench-body"><div class="input-panel"><label for="json-input">JSON document</label><textarea id="json-input" class="mono data-editor" rows="14" spellcheck="false">'+html.escape(MINIFY_SAMPLE)+'</textarea><p class="hint">Strict JSON only: no comments, trailing commas or duplicate keys.</p>'+file_field('json-file','json-file-note','Open a local UTF-8 file')+'<div id="json-indent-wrap" hidden><label for="json-indent">Formatting indentation</label><select id="json-indent"><option value="2">2 spaces</option><option value="4">4 spaces</option></select></div><div class="actions"><button class="button primary" id="json-run">Minify JSON</button><button class="button ghost" id="json-clear">Clear</button></div><div class="example-buttons"><button class="button small" data-json-example="basic">Number tokens</button><button class="button small" data-json-example="strings">String whitespace</button><button class="button small" data-json-example="invalid">Duplicate key error</button></div><p id="json-error" class="error" role="alert" hidden></p></div><div class="result-panel"><div class="result-head"><label class="mono-label" id="json-output-label" for="json-output">MINIFIED JSON</label>'+copy('json-output')+'</div><textarea id="json-output" class="mono data-editor" rows="16" readonly></textarea><p class="result-sub" id="json-status" role="status">JavaScript enables formatting and validation.</p><dl class="json-byte-stats"><div><dt>Input UTF-8</dt><dd id="json-input-bytes">—</dd></div><div><dt>Result UTF-8</dt><dd id="json-output-bytes">—</dd></div><div><dt>Byte change</dt><dd id="json-savings">—</dd></div></dl><div class="actions"><button class="button" id="json-download" disabled>Download JSON</button></div><p class="hint">Editing input or changing mode clears the previous result. Text and files stay in this browser.</p></div></div></section>'
    minify += ad_slot('tool_primary')+docs('How to minify JSON safely', 'Paste a JSON document or open a UTF-8 file, then choose Minify. The tool validates the complete document before removing insignificant whitespace. Format adds indentation; Validate keeps the original valid layout. Copy or download only the current successful result.', 'Source tokens → strict syntax check → chosen layout', [
        ('Does this preserve large integers and exponents?', 'Yes. Output is built from the original number tokens rather than converting them to JavaScript numbers. 9007199254740993, -0, 1.2300 and 1e+500 retain their original spelling. This is layout processing; downstream applications can still apply their own number limits.'),
        ('What happens to whitespace and escapes inside strings?', 'String tokens are preserved exactly, including significant spaces, escaped newlines, Unicode escapes and escaped slashes. Only whitespace outside strings is removed or replaced. Formatting does not decode a JSON string into a document.'),
        ('Are duplicate keys, comments or trailing commas accepted?', 'No. Object keys are checked after escape decoding, so "a" and "\\u0061" are duplicates. Comments, trailing commas, incomplete values and unpaired Unicode surrogates are rejected. Syntax errors include the parser’s line and column; input is not automatically repaired.'),
        ('How is the byte saving measured?', 'Input and result are encoded as UTF-8 and measured directly. A multibyte character such as an emoji is not counted as one byte. Format can increase size; the display says larger when it does. An initial BOM is removed from output and is included in the original input byte count.'),
        ('Is minification the same as gzip or Brotli?', 'No. Minification changes whitespace in the text representation. Gzip and Brotli compress transmitted bytes using different algorithms. This page reports uncompressed UTF-8 byte changes and makes no fixed percentage or network transfer claim.'),
        ('What input sizes and document shapes work?', 'Objects, arrays and valid primitive roots are accepted. Input is limited to 1,000,000 UTF-16 code units, local files to 2 MB, nesting to 80 levels, and values plus fields to 50,000. Output is capped at 3,000,000 UTF-16 code units. JSON Schema validation and sorting into a canonical signature format are outside this tool.'),
    ], '<a href="https://www.rfc-editor.org/rfc/rfc8259">RFC 8259: JSON syntax</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/API/TextEncoder">MDN: UTF-8 TextEncoder</a>')
    minify += extra_section('json-layout-example','What changes, and what stays exact','A document can lose layout spaces without losing the content inside a string or changing the spelling of a number.', '<div class="code-grid"><div class="code-example"><h3>Input JSON</h3><pre><code>'+html.escape(MINIFY_SAMPLE)+'</code></pre></div><div class="code-example"><h3>Minified JSON</h3><pre><code>'+html.escape('{"id":9007199254740993,"message":"keep  two spaces","values":[1e+30,true,null]}')+'</code></pre></div></div><p>Both spaces between <code>keep</code> and <code>two</code> belong to the string. The large identifier and exponent are copied as source tokens. Field order also stays as written; formatting is not a canonicalization algorithm.</p><p>If your input begins and ends with quotes and contains escaped JSON inside, use <a href="/json-unescape/">JSON unescape</a> or read <a href="/guides/json-double-encoding/">JSON encoding layers</a>. To find value changes between documents, use <a href="/json-compare/">JSON compare</a>. For record output, <a href="/csv-to-json/#csv-to-jsonl">CSV to JSON Lines</a> creates one record per physical line.</p>')
    minify += ad_slot('tool_secondary')+related('json-minify')

    compare = tool_head('json-compare','DATA FORMATS','Compare JSON documents','Find added, removed and changed values by JSON Pointer path. Object member order is ignored; array order, value types and missing fields stay explicit.')
    compare += '<section class="workbench compare-workbench"><div class="bench-toolbar"><strong>Structural JSON comparison</strong><span class="quiet">Object order ignored · array indexes matter</span></div><div class="bench-body">'
    for side, sample in [('left',COMPARE_LEFT),('right',COMPARE_RIGHT)]:
        compare += '<div class="input-panel compare-editor"><label for="compare-'+side+'">'+side.title()+' JSON document</label><textarea id="compare-'+side+'" class="mono data-editor" rows="14" spellcheck="false">'+html.escape(sample)+'</textarea>'+file_field('compare-'+side+'-file','compare-'+side+'-file-note','Open '+side+' UTF-8 file')+'</div>'
    compare += '</div><div class="compare-actions"><div class="actions"><button class="button primary" id="compare-run">Compare JSON</button><button class="button" id="compare-swap">Swap documents</button><button class="button ghost" id="compare-clear">Clear both</button></div><div class="example-buttons"><button class="button small" data-compare-example="basic">Changed records</button><button class="button small" data-compare-example="equal">Same values, new layout</button><button class="button small" data-compare-example="precision">Exact numbers</button><button class="button small" data-compare-example="paths">Paths & types</button></div><p id="compare-error" class="error" role="alert" hidden></p></div><section class="diff-results" aria-labelledby="diff-title"><div class="result-head"><h2 id="diff-title">Comparison result</h2><div class="actions">'+copy('compare-report','Copy report')+'<button class="button small" id="compare-download" disabled>Download report</button></div></div><p id="compare-summary" role="status">JavaScript enables structural comparison.</p><p id="compare-limit" class="notice" hidden>This report is incomplete. Up to 200 differences and 500,000 serialized preview characters are listed; more differences exist.</p><p class="table-scroll-hint" id="compare-scroll-hint" hidden>Scroll the table horizontally to view both values.</p><div id="compare-table-wrap" class="table-wrap" role="region" aria-label="JSON differences" tabindex="0" hidden><table class="diff-table"><thead><tr><th scope="col">JSON Pointer path</th><th scope="col">Change</th><th scope="col">Left value</th><th scope="col">Right value</th></tr></thead><tbody id="compare-rows"></tbody></table></div><span id="compare-report" hidden></span><p class="hint">Values over 500 characters are previews. Reports contain these previews, not a complete patch. Editing either document clears the previous report.</p></section></section>'
    compare += ad_slot('tool_primary')+docs('How this JSON comparison works','Paste a document on each side, or open local files, and select Compare JSON. The result follows field names and array indexes rather than matching text lines. Differences show a path, a change type and the value on each side. No changes are applied to either input.', 'Object keys: unordered · Arrays: ordered · Numbers: exact decimal values', [
        ('Does rearranging object keys count as a change?', 'No. {"a":1,"b":2} and {"b":2,"a":1} compare equal. String escape spellings that decode to the same valid string also compare equal. Whitespace and object member display order are ignored; the tool separately reports when the source texts differ.'),
        ('Does array order matter?', 'Yes. Arrays compare by zero-based index. Moving a value may appear as several changed indexes. Appended values are added; removed trailing values are removed. This is not a move detector or an unordered collection matcher.'),
        ('Are large numbers rounded before comparison?', 'No. Number source tokens are compared as exact base-10 values without converting to JavaScript Number. 1, 1.0 and 10e-1 match. 9007199254740992 and 9007199254740993 differ. -0 and 0 match by this tool’s policy. Number tokens are limited to 4,096 characters; exponents are normalized without expanding zeros.'),
        ('How are missing fields, null and types represented?', 'A missing field is added or removed; it is not treated as null. JSON null differs from the string "null", and number 1 differs from string "1". If a value changes type, the report shows that value at its path rather than guessing a conversion.'),
        ('What do /, ~0 and ~1 mean in a path?', 'Paths follow JSON Pointer escaping: ~ becomes ~0 and / inside a key becomes ~1. Array positions are decimal indexes. The empty pointer refers to the root and is displayed as (root); / by itself refers to an object key that is an empty string. A pointer identifies a value, not an executable command.'),
        ('What does the report include, and what are the limits?', 'Each document is limited to 1,000,000 UTF-16 code units, files to 2 MB, nesting to 80 levels, and values plus fields to 50,000. Duplicate keys, malformed syntax and unpaired Unicode surrogates are rejected. At most 200 differences and 500,000 serialized preview characters are listed, and a visible notice marks incomplete reports. A reported difference path must fit within 4,096 characters. Individual values are previewed up to 500 characters. Downloaded JSON contains the same previews and truncation flags; it is not a full replacement document or JSON Patch.'),
    ], '<a href="https://www.rfc-editor.org/rfc/rfc6901">RFC 6901: JSON Pointer</a> · <a href="https://www.rfc-editor.org/rfc/rfc8259">RFC 8259: JSON</a>')
    compare += extra_section('json-comparison-rules','Read a difference without losing its meaning','Use the change type and value type together. The same text can have a different meaning when it belongs to a JSON string.', '<div class="table-wrap"><table><thead><tr><th>Left</th><th>Right</th><th>Result</th></tr></thead><tbody><tr><td><code>{"a":1,"b":2}</code></td><td><code>{"b":2,"a":1.0}</code></td><td>Same values; different source text</td></tr><tr><td><code>{}</code></td><td><code>{"note":null}</code></td><td>Added at /note</td></tr><tr><td><code>{"n":1}</code></td><td><code>{"n":"1"}</code></td><td>Changed type at /n</td></tr><tr><td><code>["red","blue"]</code></td><td><code>["blue","red"]</code></td><td>Changed at /0 and /1</td></tr><tr><td><code>{"a/b":{"~key":1}}</code></td><td><code>{"a/b":{"~key":2}}</code></td><td>Changed at /a~1b/~0key</td></tr></tbody></table></div><p>This tool compares valid JSON values; it does not validate them against a JSON Schema, infer a primary key, merge changes, or compare JSON Lines files. Use <a href="/json-minify/">JSON format and validate</a> to inspect one document, <a href="/json-unescape/">JSON unescape</a> for a quoted string containing JSON, and <a href="/yaml-to-json/">YAML to JSON</a> for supported YAML input.</p>')
    compare += ad_slot('tool_secondary')+related('json-compare')
    note='<noscript><p class="hint">JavaScript enables local processing, file reading, copy and download. The examples and comparison policies remain readable.</p></noscript>'
    return [
        ('json-minify','JSON Minify, Formatter & Validator','Minify, format and validate JSON locally. Preserve large number tokens and string escapes; measure actual UTF-8 bytes, then copy or download.',minify+note),
        ('json-compare','Compare JSON Online — Structural JSON Diff','Compare JSON documents locally with exact numbers, unordered object keys and ordered arrays. Find added, removed and changed values by JSON Pointer.',compare+note),
    ]
